UPDATE courses SET
    course_description = '<div class="elementor-widget-container"> <strong>Brief:</strong> Embark on a journey to fluency and confidence with our General English (ELICOS) Courses. Designed for international students, our programs equip you with essential language skills for navigating Australian society and succeeding in further academic pursuits. Whether you aspire to advance your studies or immerse yourself in local culture, our courses serve as your pathway to success. </div>',
    total_course_duration = 'Upto 56 Weeks',
    offshore_tuition_fee = '300/week',
    enrolment_fee = 400,
    materials_fee = 20,
    entry_requirements = '<div class="elementor-widget-container"> <ul> <li>Basic computer skills.</li> <li>Regular class attendance and active participation.</li> <li>Approximately 4 hours of weekly self-study.</li> <li>Completion of assessment tasks with academic integrity. (Plagiarism, collusion, or any form of cheating, including using artificial intelligence, will result in a D grade for assessments and may lead to disciplinary measures).</li> <li>Fulfillment of Student Visa requirements.</li> </ul> </div> <br/> <div class="elementor-widget-container"> <ul> <li>Age: 18 years or older.</li> <li>English Language: No basic requirement. Entry to an appropriate ELICOS Course Level is determined by student’s current language proficiency level which will be assessed based on their: <ol> <li>IELTS score or its equivalent OR</li> <li>The result of the College’s Placement Test by the administration staff and/or</li> </ol> </li> <li>If necessary, through consultation with the ELICOS Course Coordinator.</li> <li>Academic: None required.</li> </ul> </div>',
    apply_form = 'https://mint.edu.au/elicos/',
    updated_at = NOW()
